{
  "relationship": {
    "statement": "A simple pendulum's swing time (period) increases with string length and decreases with stronger gravity, while the bob's mass does not affect it. For small swings, release angle changes the swing's width and speed, not its period.",
    "formula": "T = 2\\pi\\sqrt{L / g}",
    "assumptions": [
      "The bob acts as a point mass on a massless, rigid rod.",
      "Air resistance and pivot friction are neglected.",
      "Release angles stay small so the small-angle rule holds."
    ]
  },
  "quantities": [
    {
      "id": "L",
      "label": "String length",
      "unit": "m",
      "role": "control",
      "meaning": "Distance from the pivot point to the center of the hanging bob."
    },
    {
      "id": "m",
      "label": "Bob mass",
      "unit": "kg",
      "role": "control",
      "meaning": "Mass of the pendulum bob; gravity pulls harder on heavier bobs, but inertia resists equally."
    },
    {
      "id": "g",
      "label": "Gravity",
      "unit": "m/s^2",
      "role": "control",
      "meaning": "Gravitational acceleration pulling the pendulum back toward vertical."
    },
    {
      "id": "theta0",
      "label": "Release angle",
      "unit": "deg",
      "role": "control",
      "meaning": "Starting angle from vertical, setting the swing's width and peak speed."
    },
    {
      "id": "T",
      "label": "Period",
      "unit": "s",
      "role": "result",
      "meaning": "Time required for one complete back-and-forth swing."
    },
    {
      "id": "f",
      "label": "Frequency",
      "unit": "Hz",
      "role": "result",
      "meaning": "Number of complete back-and-forth swings per second."
    },
    {
      "id": "v_max",
      "label": "Peak speed",
      "unit": "m/s",
      "role": "result",
      "meaning": "Maximum speed of the bob at the bottom of the swing."
    }
  ]
}

