    "code": "function compute(inputs, t) { const L = inputs.L; const theta0 = inputs.theta0; const g = 9.81; const T = 2 * Math.PI * Math.sqrt(L / g); const f = 1 / T; const theta0_rad = theta0 * Math.PI / 180; const omega = Math.sqrt(g / L); const theta_rad = theta0_rad * Math.cos(omega * t); const theta = theta0 * Math.cos(omega * t); const x = L * Math.sin(theta_rad); const y = -L * Math.cos(theta_rad); const v_max = theta0_rad * Math.sqrt(g * L); const v_tan = -v_max * Math.sin(omega * t); const vx_tip = x + 0.35 * v_tan * Math.cos(theta_rad); const vy_tip = y + 0.35 * v_tan * Math.sin(theta_rad); const L_ref = 1.0; const theta0_ref = 15; const theta0_ref_rad = theta0_ref * Math.PI / 180; const omega_ref = Math.sqrt(g / L_ref); const theta_ref_rad = theta0_ref_rad * Math.cos(omega_ref * t); const theta_ref = theta0_ref * Math.cos(omega_ref * t); const x_ref = L_ref * Math.sin(theta_ref_rad); const y_ref = -L_ref * Math.cos(theta_ref_rad); return { T: T, f: f, v_max: v_max, theta: theta, theta_ref: theta_ref, x: x, y: y, vx_tip: vx_tip, vy_tip: vy_tip, x_ref: x_ref, y_ref: y_ref, is_longer: L > 1.05, is_shorter: L < 0.95, is_wider: theta0 > 15 }; }",
